package com.buildertoolbox.client.utils.player;
import net.minecraft.client.MinecraftClient; import net.minecraft.util.math.Vec3d; import java.util.ArrayDeque;
/** Visible vanilla rotations. Callbacks run after the next normal movement update. */
public final class Rotations {private static final ArrayDeque<Runnable> pending=new ArrayDeque<>(); public static void rotate(double yaw,double pitch,int priority,Runnable action){var p=MinecraftClient.getInstance().player;if(p==null)return;p.setYaw((float)yaw);p.setPitch((float)pitch);pending.add(action);} public static void flush(){int n=pending.size();while(n-->0)pending.removeFirst().run();} public static void clear(){pending.clear();} public static double getYaw(Vec3d target){var p=MinecraftClient.getInstance().player;return Math.toDegrees(Math.atan2(target.z-p.getZ(),target.x-p.getX()))-90;} public static double getPitch(Vec3d target){var eye=MinecraftClient.getInstance().player.getEyePos();return -Math.toDegrees(Math.atan2(target.y-eye.y,Math.hypot(target.x-eye.x,target.z-eye.z)));} }